select BOOKSET_ID BOOKSET_ID, BALANCE_DATE BALANCE_DATE, SUBJECT_NO SUBJECT_NO, FSUBJECT_NO FSUBJECT_NO, SUBJECT_LEVEL SUBJECT_LEVEL, BAL_FLAG BAL_FLAG, BAL_CO_FLAG BAL_CO_FLAG, O_CCY O_CCY, O_AMT O_AMT, O_C_AMT O_C_AMT, O_D_AMT O_D_AMT, O_CO_AMT O_CO_AMT, O_CO_C_AMT O_CO_C_AMT, O_CO_D_AMT O_CO_D_AMT, B_CCY B_CCY, B_AMT B_AMT, B_C_AMT B_C_AMT, B_CO_AMT B_CO_AMT, B_CO_C_AMT B_CO_C_AMT, B_CO_D_AMT B_CO_D_AMT, B_D_AMT B_D_AMT, TDY_O_AMT TDY_O_AMT, TDY_O_C_AMT TDY_O_C_AMT, TDY_O_D_AMT TDY_O_D_AMT, TDY_O_CO_AMT TDY_O_CO_AMT, TDY_O_CO_C_AMT TDY_O_CO_C_AMT, TDY_O_CO_D_AMT TDY_O_CO_D_AMT, TDY_B_AMT TDY_B_AMT, TDY_B_C_AMT TDY_B_C_AMT, TDY_B_D_AMT TDY_B_D_AMT, TDY_B_CO_AMT TDY_B_CO_AMT, TDY_B_CO_C_AMT TDY_B_CO_C_AMT, TDY_B_CO_D_AMT TDY_B_CO_D_AMT, IS_LEAF IS_LEAF, NUM_AMT NUM_AMT, CREATE_USER CREATE_USER, CREATE_DEPT CREATE_DEPT, CREATE_TIME CREATE_TIME, UPDATE_USER UPDATE_USER, UPDATE_TIME UPDATE_TIME, TDY_AMT_FLAG TDY_AMT_FLAG, TDY_CO_FLAG TDY_CO_FLAG, TDY_PUR_O_D_ULAMT TDY_PUR_O_D_ULAMT, TDY_RED_O_D_ULAMT TDY_RED_O_D_ULAMT, TDY_PUR_O_C_ULAMT TDY_PUR_O_C_ULAMT, TDY_RED_O_C_ULAMT TDY_RED_O_C_ULAMT, TDY_PUR_B_D_ULAMT TDY_PUR_B_D_ULAMT, TDY_RED_B_D_ULAMT TDY_RED_B_D_ULAMT, TDY_PUR_B_C_ULAMT TDY_PUR_B_C_ULAMT, TDY_RED_B_C_ULAMT TDY_RED_B_C_ULAMT from BOK_BALANCE bb where 1 = 1 and (bb.SUBJECT_NO like '6%' or bb.subject_no='4003') and DATE_FORMAT(bb.BALANCE_DATE,'%Y-%m-%d')>=#{vdate} and DATE_FORMAT(bb.BALANCE_DATE,'%Y-%m-%d')<=#{mdate}
AND bb.BOOKSET_ID in
#{item}
order by bb.BOOKSET_ID,bb.BALANCE_DATE

select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like concat_ws('','%' , #{search} , '%')
ORDER BY sdl.ITEM_CODE asc
